html:
{%- set settings = frappe.get_cached_doc("VastraFlow Settings") -%}
{%- set logo = doc.logo_file or settings.company_logo -%}
<div class="vf-job-card">
	<style>
		.vf-job-card { font-family: -apple-system, "Segoe UI", Roboto, sans-serif; color: #111; }
		.vf-job-card h1 { font-size: 20px; margin: 0; letter-spacing: .5px; }
		.vf-head { display: flex; justify-content: space-between; align-items: flex-start;
			border-bottom: 2px solid #111; padding-bottom: 10px; margin-bottom: 14px; }
		.vf-meta { font-size: 12px; text-align: right; line-height: 1.6; }
		.vf-logo { max-height: 56px; max-width: 160px; }
		.vf-grid { display: flex; flex-wrap: wrap; gap: 0; margin-bottom: 16px; }
		.vf-cell { width: 25%; box-sizing: border-box; padding: 8px 10px;
			border: 1px solid #d1d5db; margin: -1px 0 0 -1px; }
		.vf-cell .lbl { font-size: 10px; text-transform: uppercase; letter-spacing: .6px; color: #6b7280; }
		.vf-cell .val { font-size: 13px; font-weight: 600; margin-top: 2px; }
		.vf-section { font-size: 12px; text-transform: uppercase; letter-spacing: 1px;
			color: #374151; border-bottom: 1px solid #111; padding-bottom: 4px; margin: 18px 0 8px; }
		table.vf-sizes { width: 100%; border-collapse: collapse; font-size: 12px; }
		table.vf-sizes th, table.vf-sizes td { border: 1px solid #9ca3af; padding: 5px 6px; text-align: center; }
		table.vf-sizes th { background: #f3f4f6; font-weight: 600; }
		table.vf-sizes td.size { font-weight: 700; background: #fafafa; }
		table.vf-sizes tr.total td { font-weight: 700; background: #f3f4f6; }
		.vf-sign { display: flex; gap: 40px; margin-top: 42px; font-size: 11px; color: #374151; }
		.vf-sign div { flex: 1; border-top: 1px solid #111; padding-top: 5px; }
	</style>

	<div class="vf-head">
		<div>
			{% if logo %}<img src="{{ logo }}" class="vf-logo"><br>{% endif %}
			<h1>PRODUCTION JOB CARD</h1>
			<div style="font-size:12px;color:#6b7280;margin-top:3px">{{ doc.company }}</div>
		</div>
		<div class="vf-meta">
			<b>{{ doc.name }}</b><br>
			{{ frappe.format(doc.transaction_date, {"fieldtype": "Date"}) }}<br>
			<span style="color:#6b7280">Delivery</span>
			<b>{{ frappe.format(doc.delivery_date, {"fieldtype": "Date"}) }}</b>
		</div>
	</div>

	<div class="vf-grid">
		<div class="vf-cell" style="width:50%"><div class="lbl">Customer</div><div class="val">{{ doc.customer_name or doc.customer }}</div></div>
		<div class="vf-cell"><div class="lbl">Total Pieces</div><div class="val">{{ doc.garment_total_qty or 0 }}</div></div>
		<div class="vf-cell"><div class="lbl">PO / Reference</div><div class="val">{{ doc.po_no or "-" }}</div></div>

		<div class="vf-cell"><div class="lbl">Product Type</div><div class="val">{{ doc.product_type or "-" }}</div></div>
		<div class="vf-cell"><div class="lbl">Fabric</div><div class="val">{{ doc.fabric or "-" }}</div></div>
		<div class="vf-cell"><div class="lbl">Collar</div><div class="val">{{ doc.collar_type or "-" }}</div></div>
		<div class="vf-cell"><div class="lbl">Sleeve</div><div class="val">{{ doc.sleeve_type or "-" }}</div></div>

		<div class="vf-cell"><div class="lbl">Sublimation</div><div class="val">{{ doc.sublimation_type or "-" }}</div></div>
		<div class="vf-cell"><div class="lbl">Stitching</div><div class="val">{{ doc.stitching_type or "-" }}</div></div>
		<div class="vf-cell"><div class="lbl">Buttons</div><div class="val">{{ doc.button_quantity or "-" }}</div></div>
		<div class="vf-cell"><div class="lbl">Artwork</div><div class="val">{{ "Attached" if doc.artwork_file else "None" }}</div></div>
	</div>

	<div class="vf-section">Size Breakdown</div>
	{%- set rows = doc.size_matrix | selectattr("row_total", "gt", 0) | list -%}
	{% if rows %}
	<table class="vf-sizes">
		<thead>
			<tr>
				<th>Size</th>
				{% if doc.sleeve_type == "Full Sleeve" %}<th>Full Sleeve</th>{% endif %}
				{% if doc.sleeve_type == "Half Sleeve" %}<th>Half Sleeve</th>{% endif %}
				{% if doc.sleeve_type == "Sleeveless" %}<th>Sleeveless</th>{% endif %}
				<th>Qty</th>
			</tr>
		</thead>
		<tbody>
			{% for row in rows %}
			<tr>
				<td class="size">{{ row.size }}</td>
				{% if doc.sleeve_type == "Full Sleeve" %}<td>{{ row.full_sleeve or 0 }}</td>{% endif %}
				{% if doc.sleeve_type == "Half Sleeve" %}<td>{{ row.half_sleeve or 0 }}</td>{% endif %}
				{% if doc.sleeve_type == "Sleeveless" %}<td>{{ row.sleeveless or 0 }}</td>{% endif %}
				<td>{{ row.row_total or 0 }}</td>
			</tr>
			{% endfor %}
			<tr class="total">
				<td>TOTAL</td>
				<td>{{ doc.garment_total_qty or 0 }}</td>
				<td>{{ doc.garment_total_qty or 0 }}</td>
			</tr>
		</tbody>
	</table>
	{% else %}
	<div style="font-size:12px;color:#9ca3af">No quantities entered.</div>
	{% endif %}

	{% if doc.artwork_file %}
	<div class="vf-section">Artwork</div>
	<img src="{{ doc.artwork_file }}" style="max-width:280px;max-height:220px;border:1px solid #d1d5db;padding:4px">
	{% endif %}

	<div class="vf-sign">
		<div>Cutting</div>
		<div>Stitching</div>
		<div>Quality Check</div>
		<div>Dispatch</div>
	</div>
</div>
